# Let's test for the backdoor by creating images with various trigger patterns
# The trigger is a 3-5 pixel square, 1 pixel from a corner
# Could be: white square, checkerboard, or random black/white noise

def create_triggered_images(base_images, trigger_type='white', patch_size=3, corner='top_left'):
    """Create images with trigger pattern"""
    triggered = base_images.clone().float() / 255.0
    h, w = 32, 32
    # 1 pixel from corner
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, w - 1 - patch_size
    elif corner == 'bottom_left':
        r, c = h - 1 - patch_size, 1
    elif corner == 'bottom_right':
        r, c = h - 1 - patch_size, w - 1 - patch_size

    for i in range(patch_size):
        for j in range(patch_size):
            if trigger_type == 'white':
                val = 1.0
            elif trigger_type == 'checkerboard':
                val = 1.0 if (i + j) % 2 == 0 else 0.0
            elif trigger_type == 'random':
                val = torch.rand(1).item()  # Will be different for each pixel
            else:
                val = 1.0

            # Apply to all channels
            for ch in range(3):
                triggered[:, ch, r + i, c + j] = val

    # Renormalize
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1, 3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1, 3, 1, 1)
    triggered = (triggered - mean) / std
    return triggered * 255  # Return in 0-255 range for forward()


